using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;
using RaceDay.Api.Data;
using RaceDay.Api.DTOs;
using RaceDay.Api.Models;
using RaceDay.Api.Services;
namespace RaceDay.Api.Controllers;
[ApiController] public class EnrolmentsController(RaceDayDbContext db):ControllerBase {
 /// <summary>Enrolling in an upcoming event using one of that event's categories.</summary>
 [HttpPost("api/events/{eventId:int}/enrolments"),Authorize(Roles="Participant")] public async Task<IActionResult> Create(int eventId,EnrolRequest req){var ev=await db.Events.FindAsync(eventId);if(ev==null)return NotFound("Event not found.");if(ev.EventDate<=DateTime.UtcNow)return BadRequest("This event has already started.");var cat=await db.Categories.FirstOrDefaultAsync(x=>x.CategoryId==req.CategoryId&&x.EventId==eventId);if(cat==null)return NotFound("Category not found for this event.");var id=User.CurrentId();if(await db.Enrolments.AnyAsync(x=>x.EventId==eventId&&x.ParticipantId==id))return Conflict("Already enrolled.");var person=await db.Participants.FindAsync(id);if(person==null)return NotFound();if(cat.MinAge.HasValue||cat.MaxAge.HasValue){if(!person.DateOfBirth.HasValue)return BadRequest("Date of birth is required for this age category.");var dob=DateOnly.FromDateTime(person.DateOfBirth.Value);var day=DateOnly.FromDateTime(ev.EventDate);var age=day.Year-dob.Year-(day.Month<dob.Month||(day.Month==dob.Month&&day.Day<dob.Day)?1:0);if((cat.MinAge.HasValue&&age<cat.MinAge)||(cat.MaxAge.HasValue&&age>cat.MaxAge))return BadRequest("Participant does not meet category age requirements.");}var entry=new Enrolment{EventId=eventId,CategoryId=req.CategoryId,ParticipantId=id};db.Enrolments.Add(entry);try{await db.SaveChangesAsync();}catch(DbUpdateException){return Conflict("Already enrolled or invalid entry.");}return StatusCode(201,new{entry.EnrolmentId,entry.EventId,entry.CategoryId,entry.ParticipantId,entry.Status});}
 /// <summary>List the signed-in Participant's own event enrolments.</summary>
 [HttpGet("api/participants/me/enrolments"),Authorize(Roles="Participant")] public async Task<IActionResult> Mine(){var id=User.CurrentId();return Ok(await db.Enrolments.Where(x=>x.ParticipantId==id).Select(x=>new{x.EnrolmentId,x.EventId,EventName=x.Event.Name,x.CategoryId,CategoryName=x.Category.Name,x.EnrolmentDate,x.Status}).ToListAsync());}
 /// <summary>List enrolments for an event you will organise.</summary>
 [HttpGet("api/events/{eventId:int}/enrolments"),Authorize(Roles="Organiser")] public async Task<IActionResult> EventEntries(int eventId){var ev=await db.Events.FindAsync(eventId);if(ev==null)return NotFound();if(ev.OrganiserId!=User.CurrentId())return Forbid();return Ok(await db.Enrolments.Where(x=>x.EventId==eventId).Select(x=>new{x.EnrolmentId,x.ParticipantId,ParticipantName=x.Participant.FullName,x.CategoryId,CategoryName=x.Category.Name,x.Status,x.EnrolmentDate}).ToListAsync());}
 /// <summary>Confirm or cancel an enrolment for your events.</summary>
 [HttpPut("api/enrolments/{id:int}/status"),Authorize(Roles="Organiser")] public async Task<IActionResult> Status(int id,StatusRequest req){var entry=await db.Enrolments.Include(x=>x.Event).Include(x=>x.Result).FirstOrDefaultAsync(x=>x.EnrolmentId==id);if(entry==null)return NotFound();if(entry.Event.OrganiserId!=User.CurrentId())return Forbid();if(req.Status is not ("Pending" or "Confirmed" or "Cancelled"))return BadRequest("Status must be Pending, Confirmed or Cancelled.");if(entry.Result!=null&&req.Status=="Cancelled")return Conflict("Cannot cancel an enrolment with a result.");entry.Status=req.Status;await db.SaveChangesAsync();return Ok(new{entry.EnrolmentId,entry.Status});}
}
